CREATE TABLE goals (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, subject_id UUID REFERENCES subjects(id) ON DELETE SET NULL, goal_type VARCHAR(50) NOT NULL, target_value NUMERIC(10,2) NOT NULL CHECK (target_value >= 0), unit VARCHAR(30) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, status VARCHAR(30) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT chk_goals_period CHECK (end_date >= start_date));
CREATE INDEX idx_goals_user_period ON goals(user_id, start_date, end_date);
